package com.qrid.servlet;
import com.qrid.dao.*;import com.qrid.model.User;import com.qrid.util.Flash;import javax.servlet.*;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import java.io.IOException;
@WebServlet("/login") public class LoginServlet extends HttpServlet{
 protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{if(r.getSession().getAttribute("user")!=null){redirect(r,s,(User)r.getSession().getAttribute("user"));return;}r.getRequestDispatcher("/login.jsp").forward(r,s);}
 protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{String email=r.getParameter("email"),pass=r.getParameter("password");try{User u=new UserDao().authenticate(email==null?"":email.trim(),pass);if(u==null){new AuditDao().log(null,"LOGIN_FAILED","USER",email,"Invalid credentials",r.getRemoteAddr());Flash.set(r,"danger","Invalid email or password, or the account is suspended.");s.sendRedirect(r.getContextPath()+"/login");return;}r.getSession().invalidate();HttpSession session=r.getSession(true);session.setAttribute("user",u);session.setMaxInactiveInterval(1800);new AuditDao().log(u.getId(),"LOGIN","USER",String.valueOf(u.getId()),"Successful login",r.getRemoteAddr());redirect(r,s,u);}catch(Exception e){Flash.set(r,"danger","Database connection failed. Import database.sql and verify application.properties.");s.sendRedirect(r.getContextPath()+"/login");}}
 private void redirect(HttpServletRequest r,HttpServletResponse s,User u)throws IOException{String home="ADMIN".equals(u.getRole())?"/admin/dashboard":"SECURITY".equals(u.getRole())?"/security/dashboard":"/staff/dashboard";s.sendRedirect(r.getContextPath()+home);}
}
